        if (feeChangedSignificantly) {
            console2.log("Vulnerability Exists: Buy fee settings successfully altered transfer fees");
        } else {
            console2.log("Vulnerability not Exist: Buy fee settings did not affect transfer fees");
        }
    }

    function testSellFeeDuplicateSettings() public {
        console2.log("--- BEFORE: Initial Transfer without Fee ---");
